CREATE FUNCTION expire_one_staff_booking() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE candidate record;b public.bookings%ROWTYPE;BEGIN FOR candidate IN SELECT id,organization_id,property_id,room_id FROM public.bookings WHERE origin='staff' AND state='held' AND hold_deadline<=clock_timestamp() ORDER BY hold_deadline LIMIT 50 LOOP IF NOT pg_try_advisory_xact_lock(hashtextextended('inventory-location:'||candidate.organization_id::text||':'||candidate.property_id::text,0)) THEN CONTINUE;END IF;PERFORM 1 FROM public.rooms WHERE id=candidate.room_id FOR UPDATE;SELECT * INTO b FROM public.bookings WHERE id=candidate.id FOR UPDATE;IF b.state<>'held' OR b.hold_deadline>clock_timestamp() THEN CONTINUE;END IF;UPDATE public.bookings SET state='expired',version=version+1,decision_reason='Hold deadline elapsed' WHERE id=b.id;UPDATE public.room_allocations SET state='released',version=version+1,released_at=clock_timestamp() WHERE booking_id=b.id AND state='active';UPDATE public.invoices SET state='void',voided_at=clock_timestamp(),void_reason='Booking hold expired before verified payment' WHERE booking_id=b.id AND state='issued';INSERT INTO public.booking_events_outbox(organization_id,property_id,booking_id,event)VALUES(b.organization_id,b.property_id,b.id,'expired')ON CONFLICT DO NOTHING;INSERT INTO public.audit_logs(organization_id,action,object_id,details)VALUES(b.organization_id,'booking.expired',b.id,jsonb_build_object('source','worker','version',b.version+1));RETURN true;END LOOP;RETURN false;END $$;REVOKE ALL ON FUNCTION expire_one_staff_booking() FROM PUBLIC;GRANT EXECUTE ON FUNCTION expire_one_staff_booking() TO kost_worker;
CREATE FUNCTION deliver_one_booking_notification() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE e public.booking_events_outbox%ROWTYPE;BEGIN SELECT * INTO e FROM public.booking_events_outbox WHERE processed_at IS NULL ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1;IF NOT FOUND THEN RETURN false;END IF;INSERT INTO public.in_app_notifications(organization_id,property_id,user_id,event_id,booking_id,title)SELECT e.organization_id,e.property_id,m.user_id,e.id,e.booking_id,CASE WHEN e.event='accepted' THEN 'Booking disetujui; invoice awal diterbitkan' ELSE 'Hold booking kedaluwarsa; alokasi dilepas' END FROM public.memberships m WHERE m.organization_id=e.organization_id AND m.revoked_at IS NULL AND(m.role='Owner' OR(m.role IN('Manager','Finance') AND EXISTS(SELECT FROM public.location_access a WHERE a.organization_id=m.organization_id AND a.membership_id=m.id AND a.property_id=e.property_id)))ON CONFLICT(event_id,user_id)DO NOTHING;UPDATE public.booking_events_outbox SET processed_at=clock_timestamp() WHERE id=e.id;RETURN true;END $$;REVOKE ALL ON FUNCTION deliver_one_booking_notification() FROM PUBLIC;GRANT EXECUTE ON FUNCTION deliver_one_booking_notification() TO kost_worker;
